  str_season_maze_s2_help_title_705 = "Transmissão do Orbe dos Sonhos",
  str_season_maze_s2_help_disc_101 = "Os elementos instáveis dos sonhos passados ainda permanecem no reino dos sonhos, prontos para atacar a realidade a qualquer momento. Com a ajuda do Enlightener, os Navegadores agora podem se aventurar de volta aos sonhos para participar de diversos eventos de exploração, aprimorando sua proeza dentro dos sonhos. Ao derrotar o Devorador de Sonhos Supremo, há uma chance de restaurar a estabilidade da energia dos sonhos.",
  str_season_maze_s2_help_disc_102 = "Os navegadores liderarão o Enlightener, aproveitando o poder do Cartão de Divinação do Sonho, para atravessar diversos reinos de sonhos e desencadear eventos dentro deles. Ao longo da exploração, os navegadores podem convocar aurorianos e coletar Equipamento de Sonho, Orbes de Sonho e outros recursos de sonho para aprimorar suas habilidades. Após derrotar finalmente o Devorador de Sonhos e o Devorador de Sonhos Supremo, o Devaneio será concluído, rendendo ricas recompensas.",
  str_season_maze_s2_help_disc_201 = "O Enlightener avaliará o desempenho dos Navegadores nos sonhos e registrará suas pontuações. Acumule pontos suficientes para obter recompensas correspondentes.",
  str_season_maze_s2_help_disc_202 = "Após cada exploração, o Enlightener registrará a pontuação correspondente com base no Nível do Sonho e no Progresso da Exploração. Acumule pontos suficientes para atingir certos marcos e ganhar recompensas correspondentes. Além disso, você pode obter pontos extras ao completar as Missões do Sonho.",
  str_season_maze_s2_help_disc_203 = "Quando seus pontos acumulados atingem certos marcos, você pode reivindicar as recompensas correspondentes. Mais marcos de recompensa serão desbloqueados em intervalos regulares.",
  str_season_maze_s2_help_disc_204 = "Dentro dos sonhos, existem várias Missões de Sonho para realizar, que concedem pontuações adicionais ao serem concluídas.",
  str_season_maze_s2_help_disc_301 = "Os sonhos são estruturados em vários níveis. Quanto maior o nível, mais difícil o desafio e mais pontos são ganhos ao completá-lo. Na tela do Nível do Sonho, você pode ver o Devorador de Sonhos Ultimate ativo em cada nível para elaborar sua estratégia de exploração de acordo.",
  str_season_maze_s2_help_disc_302 = "Você começará no Nível de Sonho 1 e desbloqueará o próximo nível ao completar o atual, e alguns níveis serão abertos ao longo do tempo. O recurso Dream Orb estará disponível quando o Nível de Sonho 3 for desbloqueado, fornecendo suporte para sua exploração.",
  str_season_maze_s2_help_disc_303 = "Ao entrar em um sonho, você precisa selecionar 4 Aurorians para formar a formação inicial para exploração. Os Aurorians implantados herdarão seus Níveis de Avanço de fora dos sonhos, mas não herdarão outras estatísticas cultivadas ou níveis.",
  str_season_maze_s2_help_disc_304 = "Certos Aurorians não podem ser usados em Ecos de um Sonho, nem podem ser convocados durante as explorações; esta lista de Aurorians muda a cada instância de Ecos de um Sonho.",
  str_season_maze_s2_help_disc_401 = "Durante a exploração, os Navegadores podem se controlar e levar o Enlightener para a jornada.",
  str_season_maze_s2_help_disc_402 = "O Enlightener divide um sonho em diferentes Reinos dos Sonhos com base nas flutuações da energia do sonho. Os navegadores só podem transitar entre os Reinos dos Sonhos, cada um desencadeando diferentes eventos.",
  str_season_maze_s2_help_disc_403 = "Os navegadores podem usar o poder dos Cartões de Divinação dos Sonhos para se mover entre diferentes Reinos dos Sonhos. Os Passos de Ação nos Cartões de Divinação dos Sonhos determinam o número de Reinos dos Sonhos que os navegadores podem se mover, com alguns cartões também oferecendo recursos adicionais ou efeitos especiais. No início de cada rodada, o Enlightener vai retirar um certo número de Cartas de Divinação dos Sonhos do baralho, e os Navegadores podem selecionar uma para jogar ou arrastá-la diretamente para a tela para executar seu efeito.",
  str_season_maze_s2_help_disc_404 = "Os navegadores podem coletar diversos recursos dentro dos sonhos. Dream Coins podem comprar vários itens, Dream EXP aumenta o Nível do Sonho, Dream Interest impulsiona a quantidade de Dream Coins obtidas por rodada, e Cyclique garante a segurança e estabilidade da navegação dentro dos sonhos.",
  str_season_maze_s2_help_disc_405 = "Na Bolsa de Ferramentas, você pode ver os Aurorians implantados nesta exploração, o Dream Gear adquirido e os Cartões de Divinação dos Sonhos adicionados ao baralho.",
  str_season_maze_s2_help_disc_406 = "Memórias e emoções deixadas pelos sonhadores originais são envolvidas camada por camada em energia de sonho, formando Orbes de Sonho. Os navegadores podem visualizar os Orbes de Sonho obtidos nesta exploração aqui e equipá-los ou sintetizá-los.",
  str_season_maze_s2_help_disc_407 = "Os Devoradores de Sonhos atacarão os Navegadores após um número definido de rodadas. Apenas derrotando os Devoradores de Sonhos, os Navegadores podem continuar sua exploração de sonhos. O Devorador de Sonhos Supremo é o encontro final. Derrote-o para completar esta exploração, ganhando pontos com base no nível do sonho e no progresso da exploração.",
  str_season_maze_s2_help_disc_408 = "Aqui, os navegadores podem visualizar as condições do campo de batalha e as informações do inimigo desta batalha, permitindo que eles ajustem suas táticas. Os navegadores podem ganhar recompensas correspondentes após a conclusão do desafio, mas em caso de falha, eles precisam consumir Ressonância para outra tentativa.",
  str_season_maze_s2_help_disc_409 = "O EXP do Sonho ganho durante as explorações pode elevar o Nível de Sonho dos Navegadores, aumentando os níveis dos Aurorians e equipamentos e desbloqueando novos Cartões de Divinação do Sonho e Itens de Ajuda do Sonho para reforçar os Devaneios.",
  str_season_maze_s2_help_disc_501 = "Os navegadores podem entrar em Reinos Sonhos Perigosos para batalhar contra inimigos e ganhar a chance de escolher um Equipamento dos Sonhos após a vitória.",
  str_season_maze_s2_help_disc_502 = "Quando os Navegadores entram nos Reinos dos Sonhos Desconhecidos, eventos aleatórios são acionados. Alguns eventos exigem a retirada de 3 Cartas de Divinação dos Sonhos e a determinação da soma dos pontos. O sucesso na determinação concede recompensas correspondentes.",
  str_season_maze_s2_help_disc_503 = "Ao entrar nos Reinos dos Sonhos de Recursos, os Navegadores podem ganhar vários tipos de recompensas de recursos, incluindo Dream Coins, Dream EXP e Dream Orbs. Quanto mais passos são dados antes de entrar neste Reino dos Sonhos, mais ricas são as recompensas.",
  str_season_maze_s2_help_disc_504 = "Ao entrar nos Reinos dos Sonhos Inexplorados, os Navegadores podem atribuir Aurorians para realizar missões para ganhos contínuos. Durante a atribuição, os Aurorians não podem entrar em batalha e retornarão automaticamente após 5 rodadas.",
  str_season_maze_s2_help_disc_505 = "Ao entrar nos Reinos dos Sonhos do Tesouro, os Navegadores podem escolher uma recompensa de várias opções para obter.",
  str_season_maze_s2_help_disc_506 = "Ao entrar no Túnel do Reino dos Sonhos, os Navegadores atrasam o ataque do Devorador de Sonhos por 1 rodada.",
  str_season_maze_s2_help_disc_507 = "Entrar no Reino do Sonho Vazio não irá desencadear nenhum efeito.",
  str_season_maze_s2_help_disc_508 = "No Reino do Sonho da Divinação, os Navegadores podem gastar Dream Coins para redefinir ou remover os existentes Cartões de Divinação do Sonho.",
  str_season_maze_s2_help_disc_509 = "Nos Reinos do Sonho de Comércio, os navegadores podem trocar vários tipos de Orbes do Sonho entre si.",
  str_season_maze_s2_help_disc_510 = "O Reino dos Sonhos Seguro é onde os Navegadores se recuperam, permitindo que eles convoquem Aurorianos, comprem itens, adquiram medicamentos ou ressuscitem Aurorianos para aumentar sua força. Além disso, infundir Moedas dos Sonhos na Forja dos Sonhos pode desbloquear itens mais poderosos para desafios futuros.",
  str_season_maze_s2_help_disc_511 = "No Teletransporte do Reino dos Sonhos, você será teletransportado diretamente para os respectivos Reinos dos Sonhos sem passar por outros sonhos. Por favor, esteja ciente de que o teletransporte é apenas de mão única.",
  str_season_maze_s2_help_disc_512 = "No Dream Realm Gathering, você pode comprar Dream Gear.",
  str_season_maze_s2_help_disc_513 = "No Invocação do Reino dos Sonhos, você pode escolher um elemento e invocar um Aurorian do elemento correspondente na direção alvo. Uma vez escolhido, o elemento não pode ser alterado para uma determinada invocação.",
  str_season_maze_s2_help_disc_601 = "Os Navegadores podem convocar Aurorians para se juntar à sua formação. Os Aurorians implantados herdarão seus Níveis de Avanço de fora dos sonhos, mas não herdarão outras estatísticas ou níveis cultivados. Aumente seu Nível de Sonho para elevar o nível dos Aurorians e de seus equipamentos nos sonhos.",
  str_season_maze_s2_help_disc_602 = "O Dream Gear é o precioso conhecimento e valiosas relíquias deixadas por Dream Wayfarers corajosos o suficiente para explorar sonhos no rio do tempo. Ele pode desencadear vários efeitos para auxiliar os navegadores em seus Daydreams.",
  str_season_maze_s2_help_disc_603 = "Os navegadores podem usar o poder dos Cartões de Divinação dos Sonhos para se mover entre diferentes Reinos dos Sonhos. Os Passos de Ação nos Cartões de Divinação dos Sonhos determinam o número de Reinos dos Sonhos que os navegadores podem se mover, com alguns cartões também oferecendo recursos adicionais ou efeitos especiais, incluindo, mas não se limitando a Moedas dos Sonhos, Juros dos Sonhos, EXP dos Sonhos, Cyclique, etc.",
  str_season_maze_s2_help_disc_604 = "Memórias e emoções deixadas pelos sonhadores originais são envolvidas camada por camada em energia de sonho, formando Orbes de Sonho. Orbes de Sonho podem aumentar o poder de combate dos Navegadores em um sonho, então tenha cuidado para não deixar o Devorador de Sonhos pegá-los!",
  str_season_maze_s2_help_disc_605 = "Quando trazidos para os sonhos, os itens do mundo real às vezes são desgastados pela energia do sonho, formando os Itens de Ajuda dos Sonhos. Cada Item de Ajuda dos Sonhos possui efeitos de assistência únicos. Use-os sabiamente para obter apoio em suas explorações.",
  str_season_maze_s2_help_disc_701 = "Existem 3 tipos de Orbes dos Sonhos: Orbes de Habilidade, Orbes de Aprimoramento e Orbes de Carregamento. Orbes de Habilidade são usados para lançar habilidades na batalha, Orbes de Aprimoramento aprimoram outros Orbes dos Sonhos equipados, e Orbes de Carregamento concedem ganhos de Energia mais rápidos na batalha.",
  str_season_maze_s2_help_disc_702 = "Em batalha, você ganha 1 ponto de Energia do Orbe dos Sonhos para cada ladrilho que seus Aurorianos movem e conectam. Após conectar os ladrilhos, se você tiver mais Energia do que a exigência de Energia dos seus Orbes dos Sonhos, as habilidades dos seus Orbes dos Sonhos equipados serão lançadas em ordem da esquerda para a direita.",
  str_season_maze_s2_help_disc_703 = "Orbes dos Sonhos vêm em 4 níveis e podem ser atualizados até Orbes dos Sonhos de 3 estrelas. Quanto maior o nível de um Orbe dos Sonhos, mais forte são seus efeitos.",
  str_season_maze_s2_help_disc_704 = "Dois Orbes dos Sonhos do mesmo nível podem ser sintetizados para obter um Orbe dos Sonhos do próximo nível. Se os dois Orbes dos Sonhos tiverem o mesmo nome, eles produzirão o mesmo Orbe dos Sonhos de um nível superior. Se os dois Orbes dos Sonhos forem diferentes, eles produzirão um Orbe dos Sonhos aleatório de um nível superior.",
  str_season_maze_s2_help_disc_705 = "Após o término de cada desafio Echoes of a Dream, as 5 Dream Orbs de nível mais alto equipadas podem ser mantidas para o próximo desafio. Quando menos de cinco Dream Orbs estão equipadas, as Dream Orbs de nível mais alto em sua mochila serão mantidas. As Dream Orbs retidas serão redefinidas para o nível 1.",
  str_season_maze_s2_guide_warn_90020101 = "Aviso: Você alcançou com sucesso o espaço entrelaçado dos sonhos. Por favor, siga a orientação de Enlightener e derrote o Devorador de Sonhos Supremo.",
  str_season_maze_s2_guide_warn_90020102 = "Aviso: Toque aqui para iniciar sua exploração.",
  str_season_maze_s2_guide_warn_90020201 = "Aviso: Após cada exploração, você receberá Pontos de Sonho de acordo com sua classificação. Acumule Pontos de Sonho e atinja certos níveis para obter suas respectivas recompensas de exploração.",
  str_season_maze_s2_guide_warn_90020202 = "Aviso: Derrote os Devoradores de Sonhos e complete as Missões de Sonho para obter Pontos de Sonho.",
  str_season_maze_s2_guide_warn_90020203 = "Aviso: Os níveis de recompensa serão desbloqueados ao longo do tempo. Depois de reivindicar todas as recompensas do nível atual, você poderá ver a contagem regressiva até o próximo nível ser desbloqueado.",
  str_season_maze_s2_guide_warn_90020301 = "Aviso: Os sonhos são estruturados em vários níveis. Níveis mais altos significam desafios mais difíceis e mais pontos após a conclusão. O nível atual deve ser concluído para desafiar o próximo. Certos níveis serão desbloqueados automaticamente após um determinado período de tempo.",
  str_season_maze_s2_guide_warn_90020302 = "Análise em progresso... Um Devorador de Sonhos Supremo foi detectado e está causando estragos neste sonho. Toque no Devorador de Sonhos Supremo para ver mais informações detalhadas sobre ele.",
  str_season_maze_s2_guide_warn_90020303 = "Sugestão: Com base no elemento do Devorador de Sonhos Supremo, Enlightener sugere a seguinte escalação para esta exploração.",
  str_season_maze_s2_guide_circle_90020401 = "Explicação: Os sonhos são compostos por vários Reinos dos Sonhos, cada um dos quais desencadeia eventos diferentes.",
  str_season_maze_s2_guide_warn_90020402 = "Explicação: Use o Cartão de Adivinhação do Sonho de Enlightener para atravessar os Reinos do Sonho. O contador \"Passo de Ação\" no canto superior esquerdo exibe o número de passos dados; os efeitos especiais acionados pelo movimento são exibidos no canto inferior direito da tela.",
  str_season_maze_s2_guide_warn_90020403 = "Explicação: Selecione um Cartão de Adivinhação dos Sonhos e depois toque em Play para executar todos os seus efeitos; o mesmo pode ser feito arrastando um Cartão de Adivinhação dos Sonhos para o centro da tela.",
  str_season_maze_s2_guide_warn_90020404 = "Aviso: Você pode visualizar todos os Recursos do Sonho adquiridos durante a exploração atual aqui. Isso inclui Ouro, Juros, Rodadas, Níveis, Experiência e mais.",
  str_season_maze_s2_guide_warn_90020501 = "Aviso: Ganhe EXP de Sonho para aumentar o Nível de Sonho. Ao fazer isso, aumenta os níveis de Aurorian e de equipamentos e concede outras recompensas de recursos.",
  str_season_maze_s2_guide_warn_90020502 = "Aviso: Para continuar explorando, você deve manter um número suficiente de rodadas. Se suas rodadas chegarem a 0, a exploração terminará automaticamente.",
  str_season_maze_s2_guide_warn_90020503 = "Explicação: Em Sonhos, o Ouro pode ser usado para trocar por itens poderosos. No final de cada rodada, a quantidade de Ouro que você pode obter é igual à quantidade de Juros ganhos.",
  str_season_maze_s2_guide_warn_90020504 = "Aviso: Na Bolsa de Ferramentas, você pode verificar os Aurorians, Equipamentos dos Sonhos e Cartas de Divinação dos Sonhos que foram adicionados à formação atual. A Bolsa de Ferramentas será esvaziada ao final de cada exploração.",
  str_season_maze_s2_guide_warn_90020505 = "Aviso: O Devorador de Sonhos atacará após você fazer um certo número de movimentos. Derrote o último Devorador de Sonhos Supremo para terminar esta exploração.",
  str_season_maze_s2_guide_warn_90020601 = "Dica: Aqui, você pode visualizar as condições do campo de batalha e as informações do inimigo desta batalha para ajustar suas táticas de acordo. Como seu Enlightener, acredito que você pode elaborar a estratégia perfeita para o combate.",
  str_season_maze_s2_guide_warn_90020602 = "Dica: A vitória contra o Devorador de Sonhos rende recompensas abundantes.",
  str_season_maze_s2_guide_warn_90020603 = "Com Antecipação: Vamos derrotar o Devorador de Sonhos juntos.",
  str_season_maze_s2_guide_warn_90020701 = "Cada vez que você entra em um Reino dos Sonhos Seguro, você pode convocar um novo Aurorian para adicionar à sua formação.",
  str_season_maze_s2_guide_warn_90020702 = "Na interface de compra, você pode trocar Dream Coins por Dream Gear e itens de Dream Aid.",
  str_season_maze_s2_guide_warn_90020703 = "Após armazenar uma quantidade designada de Dream Coins na Dream Forge, você pode desbloquear itens de sonho ainda mais poderosos e outros efeitos especiais.",
  str_season_maze_s2_guide_warn_90020704 = "A Caixa de Medicamentos pode ser usada para curar os Aurorianos em sua formação atual à custa de Moedas dos Sonhos. Lembre-se de manter sua equipe saudável!",
  str_season_maze_s2_guide_warn_90020705 = "Se algum Aurorian for incapacitado em batalha, ele pode ser revivido na Sala de Operações ao custo de Moedas de Sonho.",
  str_season_maze_s2_guide_warn_90020706 = "Após descansar, toque no botão \"Iniciar Próxima Rodada\" para continuar o desafio.",
  str_season_maze_s2_guide_warn_90020801 = "Aurorians podem ser enviados para completar missões em Reinos dos Sonhos Inexplorados. Aurorians enviados retornarão após um número definido de rodadas, juntamente com as Recompensas de Expedição de suas missões. Aurorians que atendem aos Requisitos de Expedição de suas missões ganharão recompensas adicionais.",
  str_season_maze_s2_guide_warn_90020802 = "Toque aqui para selecionar um Aurorian para despacho. Aurorians despachados não podem ser adicionados à formação até que retornem.",
  str_season_maze_s2_guide_warn_90020901 = "No Reino do Sonho de Comércio, o Navegador pode trocar Orbes de Sonho com aliados atualmente em outros Sonhos, aumentando assim seus efeitos.",
  str_season_maze_s2_guide_warn_90020902 = "Cada instância de um Trade Dream Realms fornece ao Navegador 6 oportunidades de negociação para Dream Orbs, e cada aliado só pode ser negociado uma vez.",
  str_season_maze_s2_guide_warn_90020903 = "Toque em um Orbe dos Sonhos para iniciar uma troca. Os Orbes dos Sonhos recém-obtidos herdarão a classificação dos originais.",
  str_season_maze_s2_guide_warn_90021001 = "No Reinos de Sonho de Divinação, o Navegador pode gastar Moedas de Sonho para redefinir ou deletar os Cartões de Divinação de Sonho atualmente possuídos.",
  str_season_maze_s2_guide_warn_90021002 = "As atuais Cartas de Divinação dos Sonhos do Navegador são exibidas abaixo. Toque e arraste um cartão para redefinir ou excluí-lo.",
  str_season_maze_s2_guide_warn_90021003 = "Arraste um Cartão de Divinação do Sonho para este local e gaste a quantidade necessária de Ouro para excluí-lo. O custo em Ouro aumenta a cada exclusão de cartão.",
  str_season_maze_s2_guide_warn_90021004 = "Arraste um Cartão de Adivinhação dos Sonhos para este local e gaste a quantidade necessária de Ouro para redefini-lo, o que exclui o cartão atual e produz um novo. O custo em Ouro aumenta a cada redefinição de cartão.",
  str_season_maze_s2_mail_gm_season = "Ecos de um Sonho",
  str_season_maze_s2_mail_title_season = "Recompensas Não-retiradas",
  str_season_maze_s2_mail_detail_season = "O evento Echoes of a Dream acabou! Aqui estão as recompensas que você não conseguiu retirar durante o evento!"
}
